import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第十九卦 临 地泽临 坤上兑下","description":"周易 - 第十九卦 临 地泽临 坤上兑下","frontmatter":{"title":"第十九卦 临 地泽临 坤上兑下","description":"周易 - 第十九卦 临 地泽临 坤上兑下"},"headers":[],"relativePath":"zh/classics/zhouyi/020.md","filePath":"zh/classics/zhouyi/020.md"}'),l={name:"zh/classics/zhouyi/020.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="临" tabindex="-1">临 <a class="header-anchor" href="#临" aria-label="Permalink to “临”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>元，亨，利，贞。至于八月有凶。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>临，刚浸而长。说而顺，刚中而应，大亨以正，天之道也。至于八月有凶，消不久也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>泽上有地，临；君子以教思无穷，容保民无疆。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>咸临，贞吉。象曰：咸临 贞吉，志行正也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>咸临，吉无不利。象曰：咸临，吉无不利；未顺命也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>甘临，无攸利。既忧之，无咎。象曰：甘临，位不当也。既忧之，咎不长也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>至临，无咎。象曰：至临无咎，位当也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>知临，大君之宜，吉。象曰：大君之宜，行中之谓也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>敦临，吉无咎。象曰：敦临之吉，志在内也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
